INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65846757', 65846757, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'KOMISI PENYIARAN INDONESIA', 'Pengadaan Penyedia Jasa Lainnya Perorangan (PJLP) Analis Mahir Pengawasan Isi Siaran, Asisten Komisioner, dan Sekretaris Komisioner KPI Pusat TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 2461032000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 456, THN, @ 5397000 )', 'Pengadaan Penyedia Jasa Lainnya Perorangan (PJLP) Analis Mahir Pengawasan Isi Siaran, Asisten Komisioner, dan Sekretaris Komisioner KPI Pusat TA 2026 sebanyak total 30 (tiga puluh) orang', '1. PERSYARATAN UMUM a. Warga Negara Indonesia; b. Usia minimal 20 (dua puluh) tahun pada tanggal 1 Januari 2026; c. Memiliki Nomor Pokok Wajib Pajak (NPWP); d. Sanggup bekerja sama dalam tim dan bekerja sesuai target waktu; e. Sehat Jasmani dan Rohani; f. Menguasai aplikasi perkantoran; g. Mampu menyiapkan bahan laporan; dan h. Loyal dan bertanggung jawab atas pekerjaan. 2. PERSYARATAN KHUSUS a. PJLP Analis Mahir Pengawasan Isi Siaran i. Pendidikan Minimal D3 diutamakan di bidang Komunikasi, Penyiaran, Manajemen, Jurnalistik, sekretaris dan/atau S1 di bidang Ilmu Komunikasi, Penyiaran, Jurnalistik, Hubungan Masyarakat, Ilmu Politik. Hukum, Sastra/Bahasa Indonesia; ii. Memiliki Pengalaman bekerja di Komisi Penyiaran Indonesia minimal 6 (enam) bulan dengan dibuktikan Surat Keterangan dari Sekretaris KPI; iii. Diutamakan memiliki sertifikat Sekolah P3 dan SPS; iv. Mampu mengidentifikasi pelanggaran isi siaran di Lembaga Penyiaran yang berpotensi melanggar P3 dan SPS; dan v. Mampu mengoperasikan komputer, baik aplikasi ms. office maupun internet dan memiliki kemampuan berbahasa inggris (minimal pasif). b. PJLP Asisten Anggota i. Minimal Strata Satu (S1); ii. Minimal 6 (enam) bulan bekerja di bidang yang sama; iii. Mampu mengidentifikasi pokok dari tugas dan fungsi lembaga Komisi Penyiaran Indonesia; iv. Mampu bekerjasama dengan tim dan bekerja dengan tenggat waktu; v. Memiliki kemampuan komunikasi yang baik dan mampu menjadi juru bicara Anggota KPI; dan vi. Dapat mengoperasikan komputer, baik aplikasi office maupun internet, memiliki kemampuan berbahasa Inggris (minimal pasif). c. PJLP Sekretaris Anggota i. Minimal Strata Satu (S1); ii. Minimal 6 (enam) bulan bekerja di bidang yang sama; iii. Mampu mengidentifikasi pokok dari tugas dan fungsi lembaga Komisi Penyiaran Indonesia; iv. Mampu bekerjasama dengan tim dan bekerja dengan tenggat waktu; dan v. Dapat mengoperasikan komputer, baik aplikasi office maupun internet, memiliki kemampuan berbahasa Inggris (minimal pasif). d. PJLP Staf Administrasi i. Minimal Strata Satu (S1); ii. Minimal 6 (enam) bulan bekerja di bidang yang sama; iii. Mampu mengidentifikasi pokok dari tugas dan fungsi lembaga Komisi Penyiaran Indonesia; iv. Mampu bekerjasama dengan tim dan bekerja dengan tenggat waktu; dan v. Dapat mengoperasikan komputer, baik aplikasi office maupun internet, memiliki kemampuan berbahasa Inggris (minimal pasif).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2379395);
